def main():
    print("================================================================================")
    print("        BEAL CONJECTURE COMPREHENSIVE REPRODUCIBILITY & AUDIT SUITE             ")
    print("================================================================================")
    total = len(MILESTONES)
    passed = 0
    failures = []
    
    t_start = time.time()
    for idx, (name, cmd) in enumerate(MILESTONES, 1):
        print(f"\n[{idx}/{total}] RUNNING: {name}", flush=True)
        print(f"       Command: {' '.join(cmd)}", flush=True)
        t0 = time.time()
        try:
            res = subprocess.run(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=120)
            elapsed = time.time() - t0
            if res.returncode == 0:
                print(f"       STATUS: [PASS] ({elapsed:.2f}s)", flush=True)
                passed += 1
            else:
                print(f"       STATUS: [FAIL] (return code {res.returncode})", flush=True)
                print("       STDERR:", res.stderr[:300], flush=True)
                failures.append((name, res.stderr))
        except subprocess.TimeoutExpired:
            print(f"       STATUS: [TIMEOUT] (exceeded 120s)")
            failures.append((name, "TimeoutExpired (exceeded 120s)"))
        except Exception as e:
            print(f"       STATUS: [EXCEPTION] {e}")
            failures.append((name, str(e)))

    t_total = time.time() - t_start
    print("\n================================================================================")
    print(f" AUDIT SUMMARY: {passed}/{total} MILESTONES PASSED IN {t_total:.2f}s")
    print("================================================================================")
    
    if failures:
        print("\nFailed Milestones:")
        for name, err in failures:
            print(f"  - {name}: {err[:150]}")
        sys.exit(1)
    else:
        print(f"\nALL {total} AUDIT CERTIFICATES AND TEST SUITES EXECUTED WITH 100% PASS RATE!")
        sys.exit(0)

if __name__ == "__main__":
    main()
